/**
 * Kiki Marine Survey App - Complete Implementation
 * All data persisted to IndexedDB
 * Service worker for offline support
 * Photo storage and annotation capabilities
 */

const APP_VERSION = 'v2466';

// v2275: Rudder pluralization — adapts labels and snippet text based on
// survey.rudderCount.  When count >= 2 every "rudder" becomes "rudders" and
// verb agreement is adjusted ("was" → "were", "is" → "are", etc.).
// Labels with the template form "Rudder(s)" or "rudder(s)" are resolved to
// the correct singular or plural.
function pluralizeRudder(text, rudderCount) {
  if (!text) return text;
  const n = parseInt(rudderCount, 10) || 1;

  // 1) Resolve "(s)" markers — "Rudder(s)" → "Rudder" or "Rudders"
  text = text.replace(/[Rr]udder\(s\)/g, (m) => {
    const cap = m.charAt(0) === 'R';
    return n >= 2 ? (cap ? 'Rudders' : 'rudders') : (cap ? 'Rudder' : 'rudder');
  });

  if (n < 2) return text;

  // ── Plural transforms (only when rudderCount >= 2) ──

  // 1b) "A/an [adjective] rudder" → "[Adjective] rudders" (drop article)
  //     e.g. "A compromised rudder represents" → "Compromised rudders represent"
  text = text.replace(/\b[Aa]n?\s+(\w+)\s+rudder\b(?!\s+(?:post|shaft|stock|core|stuffing|blade))/g, (m, adj) => {
    return adj.charAt(0).toUpperCase() + adj.slice(1) + ' rudders';
  });

  // 2) "the rudder" → "both rudders"  (but not "the rudder post/shaft/..." yet)
  text = text.replace(/\b[Tt]he rudder\b(?!\s+(?:post|shaft|stock|core|stuffing|blade))/g, (m) => {
    return m.charAt(0) === 'T' ? 'Both rudders' : 'both rudders';
  });

  // 3) "a rudder" / "A rudder" (standalone, not "a rudder post" etc.)
  text = text.replace(/\b[Aa] rudder\b(?!\s+(?:post|shaft|stock|core|stuffing|blade))/g, (m) => {
    return m.charAt(0) === 'A' ? 'The rudders' : 'the rudders';
  });

  // 4) Compound nouns: "rudder post" → "rudder posts", "rudder shaft" →
  //    "rudder shafts", "rudder stuffing box" → "rudder stuffing boxes",
  //    "rudder core" → "rudder cores", "rudder blade" → "rudder blades"
  text = text.replace(/\b(rudder) (post|shaft|stock|core|blade)s?\b/gi, (m, r, noun) => {
    return r + ' ' + noun + 's';
  });
  text = text.replace(/\b(rudder) (stuffing box)(?!es)\b/gi, (m, r, noun) => {
    return r + ' stuffing boxes';
  });

  // 5) Remaining standalone "rudder" (not already plural, not before a compound noun)
  text = text.replace(/\b([Rr])udder\b(?!s)(?!\s+(?:post|shaft|stock|core|stuffing|blade))/g, (m, cap) => {
    return cap === 'R' ? 'Rudders' : 'rudders';
  });

  // 6) Verb agreement — ONLY when "rudders" is clearly the sentence
  //    subject.  We require it to appear at sentence start (after ^, ".",
  //    "!", or "?") to avoid false positives like "on both rudders was
  //    intact" where "anti-fouling" is the real subject.
  //    Covers: "Both rudders was" → "Both rudders were"
  //            "The rudder posts was" → "The rudder posts were"
  text = text.replace(/(^|[.!?]\s+)(Both rudders)\s+was\b/gi, '$1$2 were');
  text = text.replace(/(^|[.!?]\s+)(Both rudders)\s+is\b/gi, '$1$2 are');
  text = text.replace(/(^|[.!?]\s+)(Both rudders)\s+has\b/gi, '$1$2 have');
  text = text.replace(/(^|[.!?]\s+)(The rudder (?:posts|shafts|stocks|cores|blades|stuffing boxes))\s+was\b/gi, '$1$2 were');

  // 7) Pronoun agreement: "its" → "their" when preceded by "rudders"
  //    within a short window (same sentence).
  text = text.replace(/\b(rudders\b[^.!?]{0,30}?)\bits\b/gi, '$1their');

  // 8) Singular verb after "rudders" as subject: "rudders represents" →
  //    "rudders represent". Covers common third-person-singular endings.
  text = text.replace(/\b(rudders)\s+(represents|moves|has)\b/gi, (m, subj, verb) => {
    const base = verb.toLowerCase();
    const fixed = base === 'has' ? 'have' : base.replace(/s$/, '');
    return subj + ' ' + fixed;
  });

  return text;
}

// v2405: Display-only transform for category names that carry "(s)" markers
// because the underlying survey template can't know in advance whether the
// vessel has a single or twin engine. Internal category.name strings stay
// literal ("Engine(s) and drive(s)") so identity-matching code (report
// builder, propulsion-chip injection, engine-photo sync) keeps working
// against a stable key. Callers pipe the rendered title through this helper
// to get reader-facing copy.
//
// hasTwin is resolved via engine2Make because that field is the single source
// of truth for "is this a twin-engine vessel" everywhere else in the app
// (propulsion narrative, engine-description template, report section header).
// Stays consistent if the surveyor toggles Engine 2 on/off mid-survey.
function displayCategoryName(categoryName, survey) {
  if (!categoryName) return categoryName;
  if (categoryName === 'Engine(s) and drive(s)') {
    const hasTwin = !!(survey && survey.engine2Make);
    return hasTwin ? 'Engines and drives' : 'Engine and drive';
  }
  return categoryName;
}

// v2405: smart-append "hp" to a raw horsepower string. If the value already
// contains a recognisable power unit (hp, HP, h.p., bhp, horsepower, kW) it
// is returned unchanged so surveyors who type "300 hp", "300hp", or
// "220 kW (300 hp)" don't end up with duplicated units.  No \b word
// boundaries on the unit tokens — "300hp" (no space between number and
// unit) has digit-letter transition that \b wouldn't catch, and the field
// is explicitly a horsepower value so substring false-matches aren't a
// realistic risk.
function _fmtHP(s) {
  if (!s) return s;
  if (/(hp|h\.p\.|horsepower|kw|bhp)/i.test(s)) return s;
  return `${s} hp`;
}

// Global error handlers — catch crashes on iOS and show a message instead of silently dying
window.addEventListener('error', (e) => {
  console.error('Global error:', e.error || e.message);
  try { showToast('Error: ' + (e.message || 'Unknown error').substring(0, 100)); } catch(_) {}
  try { _kkLogRemoteError({ message: e.message || 'Unknown error', stack: (e.error && e.error.stack) || '' }); } catch(_) {}
});
window.addEventListener('unhandledrejection', (e) => {
  console.error('Unhandled rejection:', e.reason);
  try { showToast('Error: ' + String(e.reason).substring(0, 100)); } catch(_) {}
  try { _kkLogRemoteError({ message: String(e.reason).substring(0, 500), stack: (e.reason && e.reason.stack) || '' }); } catch(_) {}
});
let db = null;
let textLibrary = null;
// Spell-check dictionary — lazy-loaded from dictionary.json on first use.
// ~128k English words + marine/Canadian supplement. Loaded once, cached by
// the service worker for offline field use.
let SPELL_DICT = null;
let SPELL_DICT_LOADING = false;
function loadSpellDict() {
  if (SPELL_DICT || SPELL_DICT_LOADING) return;
  SPELL_DICT_LOADING = true;
  fetch('dictionary.json')
    .then(r => r.json())
    .then(arr => {
      SPELL_DICT = new Set(arr);
      // v2176: supplement the base dictionary with marine-surveyor vocabulary
      // that general English dictionaries often miss. These are real words
      // that were being flagged as typos in inspection notes.
      const MARINE_EXTRAS = [
        'recoat', 'recoated', 'recoating', 'recoats',
        'anti-fouling', 'antifouling', 'antifouled',
        'gelcoat', 'gelcoats', 'gelcoated',
        'fibreglass', 'fibreglasses',
        'delamination', 'delaminated', 'delaminating',
        'osmotic', 'osmosis',
        'blistering', 'blister', 'blisters', 'blistered',
        'fairing', 'faired', 'fairs',
        'stanchion', 'stanchions',
        'pulpit', 'pulpits',
        'pushpit', 'pushpits',
        'saildrive', 'saildrives', 'outdrive', 'outdrives',
        'sterndrive', 'sterndrives',
        'cutlass', 'cutlasses',
        'seacock', 'seacocks',
        'skeg', 'skegs',
        'transom', 'transoms',
        'chainplate', 'chainplates',
        'coachroof', 'coachroofs',
        'chartplotter', 'chartplotters',
        'autohelm', 'autopilot', 'autopilots',
        'binnacle', 'binnacles',
        'bimini', 'biminis',
        'pontoon', 'pontoons',
        'coaming', 'coamings',
        'bulkhead', 'bulkheads',
        'bowsprit', 'bowsprits',
        'cleat', 'cleats',
        'windlass', 'windlasses',
        'genoa', 'genoas',
        'spinnaker', 'spinnakers',
        'halyard', 'halyards',
        'traveller', 'travellers',
        'lazarette', 'lazarettes',
        'knot', 'knots',
        'kts',
        'abyc', 'solas', 'nmma', 'tp1332',
        'sams',
        'heeled', 'heeling',
        'tacking', 'tack',
        'relaunch', 'relaunched', 'relaunching', 'relaunches',
        'touched-up', 'touched',
        'rocna', 'mantus', 'spade',
        'danforth', 'cqr', 'bruce', 'delta',
        'rebed', 'rebedded', 'rebedding',
        'retighten', 'retightened', 'retightening',
      ];
      MARINE_EXTRAS.forEach(w => SPELL_DICT.add(w.toLowerCase()));
      SPELL_DICT_LOADING = false;
      // Re-run tone check on any currently-open sheet textarea so the new
      // dictionary catches words already typed.
      try {
        document.querySelectorAll('textarea[id^="sheet-text-"]').forEach(ta => {
          if (window._mainSheetToneCheck) window._mainSheetToneCheck(ta);
        });
        document.querySelectorAll('[data-snippet-builder-strip]').forEach(strip => {
          if (typeof updateToneWarning === 'function') updateToneWarning(strip);
        });
      } catch (e) { /* no-op */ }
    })
    .catch(err => {
      console.warn('Spell dictionary failed to load:', err);
      SPELL_DICT_LOADING = false;
    });
}
let surveyTemplate = null;
let insuranceSurveyTemplate = null;
let boatSpecsDB = null;
let boatValuesDB = null;
