// ── Remote error logging ────────────────────────────────────────────────
// Tracks the last major user action so error reports include context.
let _kkLastAction = '';
// Rate-limit state: timestamps of recent remote log calls.
const _kkErrorTimestamps = [];
const _KK_ERROR_RATE_LIMIT = 10; // max errors per 60 s

/**
 * Fire-and-forget remote error logger.  Writes to the Firestore
 * "error_logs" collection when Firebase is available.  Silently no-ops
 * if Firebase isn't connected or rate limit is exceeded.
 */
function _kkLogRemoteError(errorInfo) {
  try {
    if (!window.fsDb) return;

    // Rate-limit: drop if we've already logged 10 errors in the last minute
    const now = Date.now();
    while (_kkErrorTimestamps.length && _kkErrorTimestamps[0] < now - 60000) {
      _kkErrorTimestamps.shift();
    }
    if (_kkErrorTimestamps.length >= _KK_ERROR_RATE_LIMIT) return;
    _kkErrorTimestamps.push(now);

    // Detect active view — use the global `currentView` plus any visible
    // bottom-sheet or modal as a hint.
    let activeView = (typeof currentView === 'string') ? currentView : 'unknown';
    try {
      const sheet = document.querySelector('.bottom-sheet[style*="translateY(0"]');
      if (sheet) activeView += '+bottomSheet';
    } catch (_) {}

    const doc = {
      appVersion:  APP_VERSION,
      timestamp:   firebase.firestore.FieldValue.serverTimestamp(),
      clientTime:  new Date().toISOString(),
      message:     String(errorInfo.message || '').substring(0, 500),
      stack:       String(errorInfo.stack || '').substring(0, 2000),
      currentView: activeView,
      surveyId:    (typeof currentSurveyId !== 'undefined' && currentSurveyId) ? currentSurveyId : null,
      lastAction:  _kkLastAction || '',
      userAgent:   navigator.userAgent,
      online:      navigator.onLine
    };

    // Fire-and-forget — intentionally not awaited
    window.fsDb.collection('error_logs').add(doc).catch(function () {});
  } catch (_) {
    // Must never throw
  }
}
// ── End remote error logging ────────────────────────────────────────────

// Persist view state to sessionStorage so reload returns to the same screen
function persistViewState() {
  try {
    sessionStorage.setItem('_currentView', currentView);
    if (currentSurveyId) sessionStorage.setItem('_currentSurveyId', currentSurveyId);
    else sessionStorage.removeItem('_currentSurveyId');
  } catch(e) {}
}

// Force update — check for new SW, activate it, let controllerchange reload.
// Single tap, no double-reload needed.
async function forceAppUpdate() {
  try {
    showToast('Checking for updates…');

    if ('serviceWorker' in navigator) {
      const reg = await navigator.serviceWorker.getRegistration();
      if (reg) {
        await reg.update();            // fetch sw.js from server
        if (reg.waiting) {
          // New version already downloaded — activate it now
          reg.waiting.postMessage({ type: 'SKIP_WAITING' });
          // controllerchange listener will reload the page
          return;
        }
        if (reg.installing) {
          // Update is downloading — wait for it to finish
          showToast('Downloading update…');
          reg.installing.addEventListener('statechange', function handler() {
            if (reg.installing && reg.installing.state === 'installed') {
              reg.installing.removeEventListener('statechange', handler);
              reg.waiting && reg.waiting.postMessage({ type: 'SKIP_WAITING' });
            }
          });
          return;
        }
      }
    }

    // Fallback: no SW or nothing new — clear caches and hard reload
    if ('caches' in window) {
      const names = await caches.keys();
      for (const n of names) await caches.delete(n);
    }
    showToast('Reloading…');
    persistViewState();
    await new Promise(r => setTimeout(r, 300));
    window.location.replace(
      window.location.origin + window.location.pathname + '?_cb=' + Date.now()
    );
  } catch (err) {
    console.error('Force update error:', err);
    persistViewState();
    window.location.replace(
      window.location.origin + window.location.pathname + '?_cb=' + Date.now()
    );
  }
}

// ── v2390: Self-heal — nuclear cache reset ─────────────────────────────
// Clears the full service-worker cache and reloads fresh from the server.
// Used when the cache has drifted out of sync with the latest deployed code
// (e.g. partial SW installs on flaky networks leave mixed-version files
// in cache, causing mysterious crashes — most recently the iOS Safari
// crash on the vessel-name input that only fresh-install or Private Mode
// could bypass).
//
// CRITICAL: IndexedDB is untouched. Surveys and photos survive the reset.
// Only HTTP cache entries (JSON, JS, images) are deleted. iOS Safari's
// "Clear Website Data" wipes IndexedDB too — this is the safer alternative.
//
// v2391: Split into a private `_doResetAppCache(silent)` helper so the
// startup version handshake can invoke the same reset without the confirm
// dialog / toasts / alert — silent mode is for "we detected cache drift,
// auto-healing now" and must not interrupt the user with prompts.
async function _doResetAppCache(silent) {
  try {
    if (!silent) showToast('Resetting app cache…');
    persistViewState();

    // Unregister every service-worker registration for this origin.
    // Without this, the old SW keeps serving stale cache even after we
    // delete the caches — a fresh page load would re-populate from the
    // old SW's fetch handler on the first offline request.
    if ('serviceWorker' in navigator) {
      const regs = await navigator.serviceWorker.getRegistrations();
      for (const reg of regs) {
        try { await reg.unregister(); } catch (_) {}
      }
    }

    // Delete every CacheStorage bucket. `caches.keys()` returns ALL cache
    // names (current + stale from prior versions). Deleting them all puts
    // us in the same state as a brand-new Safari install for this origin,
    // minus IndexedDB.
    if ('caches' in window) {
      const names = await caches.keys();
      for (const n of names) {
        try { await caches.delete(n); } catch (_) {}
      }
    }

    if (!silent) showToast('Reloading…');
    // Silent path reloads almost immediately so the user sees nothing
    // beyond a momentary page reload indicator. Explicit path waits a
    // beat so the "Reloading…" toast actually renders before nav.
    await new Promise(r => setTimeout(r, silent ? 50 : 400));

    // Hard reload with a cache-buster query. This forces the browser's
    // own HTTP cache (separate from CacheStorage above) to bypass its
    // cached copy of index.html and re-fetch from the server.
    window.location.replace(
      window.location.origin + window.location.pathname + '?_reset=' + Date.now()
    );
  } catch (err) {
    console.error('[ResetAppCache] Error:', err);
    if (!silent) {
      alert(
        'Reset failed: ' + (err && err.message ? err.message : 'unknown error') +
        '\n\nTry closing Safari completely and reopening the app.'
      );
    }
    // Silent path can't recover — rethrow so the handshake caller can log
    // and let the page continue loading with whatever cache state exists.
    throw err;
  }
}

// Public entry point — asks before nuking.
async function resetAppCache() {
  const ok = confirm(
    'Reset the app cache?\n\n' +
    'This clears cached files and reloads the app fresh from the server. ' +
    'Your surveys and photos are stored separately and are NOT affected — ' +
    'they will still be here after the reset.\n\n' +
    'Use this if the app is crashing or behaving strangely.'
  );
  if (!ok) return;
  try { await _doResetAppCache(false); } catch (_) { /* handled inside */ }
}

// ── v2391: Startup version handshake — auto-heal on cache drift ─────────
// Compares the version injected into index.html (`<meta name="app-version">`)
// against APP_VERSION in app.js. A mismatch means the browser served a fresh
// index.html but a stale app.js (or the reverse) — exactly the drift pattern
// that v2390 was added to repair. Here we repair it automatically, before
// any other startup code runs, so the user never sees a crash caused by
// mixed-version files in cache.
//
// Safety — the sessionStorage flag prevents a reload loop if the mismatch
// somehow persists across the reset (e.g. CDN returning stale files). First
// detection attempts the heal; second detection in the same session just
// logs and lets the app load as best it can. The flag clears when the tab
// is closed, so a fresh session gets a fresh attempt.
async function _checkVersionHandshake() {
  try {
    const meta = document.querySelector('meta[name="app-version"]');
    if (!meta) return; // older index.html — no meta tag, nothing to compare
    const indexVersion = (meta.getAttribute('content') || '').trim();
    const appVersion = (typeof APP_VERSION === 'string' ? APP_VERSION : '').trim();
    if (!indexVersion || !appVersion) return;
    // Normalize both sides: strip leading 'v' so 'v2391' and '2391' both match.
    const norm = s => s.replace(/^v/i, '').trim();
    if (norm(indexVersion) === norm(appVersion)) return;

    const alreadyTried = (() => {
      try { return sessionStorage.getItem('_versionHandshakeAttempted') === '1'; }
      catch (_) { return false; }
    })();
    if (alreadyTried) {
      console.warn(
        `[VersionHandshake] Mismatch persists after prior heal attempt: ` +
        `index=${indexVersion} vs app=${appVersion}. Not retrying in this session.`
      );
      return;
    }
    try { sessionStorage.setItem('_versionHandshakeAttempted', '1'); } catch (_) {}

    console.warn(
      `[VersionHandshake] Cache drift detected: index.html=${indexVersion} ` +
      `vs app.js=${appVersion}. Auto-healing…`
    );
    await _doResetAppCache(true);
  } catch (e) {
    console.error('[VersionHandshake] error:', e);
  }
}
// Fire-and-forget at module load so the handshake runs as early as possible —
// before renderHome, IndexedDB open, service-worker register, etc. If we
// detect drift, the reload happens before any of that initializes and the
// old code's state never gets rehydrated on top of a stale cache.
_checkVersionHandshake();

// ── Photo compression for reports ──────────────────────────────────────
// Resizes a dataUrl image to fit within maxDim (default 1200px) and
// re-encodes as JPEG at the given quality. This dramatically reduces
// memory when embedding photos in report HTML (iPhone photos can be
// 5-8 MB each as base64; after compression they're ~100-300 KB).
function compressPhotoForReport(dataUrl, maxDim = 1200, quality = 0.7) {
  return new Promise((resolve) => {
    // If it's not a valid data URL, return as-is
    if (!dataUrl || !dataUrl.startsWith('data:image')) {
      resolve(dataUrl);
      return;
    }
    const img = new Image();
    img.onload = () => {
      let w = img.naturalWidth;
      let h = img.naturalHeight;
      // Only resize if larger than maxDim
      if (w > maxDim || h > maxDim) {
        if (w > h) {
          h = Math.round(h * maxDim / w);
          w = maxDim;
        } else {
          w = Math.round(w * maxDim / h);
          h = maxDim;
        }
      }
      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);

      // v2244→v2247: auto-strip date stamp from report photos.
      // The stamp added by addDateStampToPhoto() sits in the bottom-right
      // corner — dark rect with white YYYY-MM-DD text, font = width/40,
      // padding 12 px. We paint over it by sampling pixels just above the
      // stamp region and tiling them down. This keeps the original photo in
      // IndexedDB intact while ensuring the printed report is date-free.
      //
      // Guards:
      //  1. Use widest possible date glyphs ('2088-08-08') for measureText
      //     plus a safety margin, so the removal region is never too narrow.
      //  2. Detect whether a stamp is actually present by checking the
      //     average brightness of the stamp region — only strip if it's
      //     dark (the stamp has rgba(0,0,0,0.7) background).
      try {
        const _fontSize = Math.max(20, Math.round(w / 40));
        const _padding = 12;
        const _margin = 8; // safety margin for font width variation
        ctx.font = `${_fontSize}px Arial, sans-serif`;
        const _tw = ctx.measureText('2088-08-08').width; // widest digit combo
        const _rw = Math.round(_tw + _padding * 2 + _margin);
        const _rh = Math.round(_fontSize + _padding + 4); // +4 matches removeDateStampFromPhoto
        const _sx = Math.max(0, w - _rw);
        const _sy = Math.max(0, h - _rh);
        if (_sx >= 0 && _sy >= 0 && _rw > 0 && _rh > 0) {
          // v2363: structural-signature detection instead of avg brightness.
          // The stamp has a dark rect (rgba(0,0,0,0.7) ≈ brightness ≤ 76
          // after alpha-blend on ANY background, even pure white) combined
          // with bright white text glyphs (brightness > 220). Natural image
          // content virtually never has that bimodal distribution in a tiny
          // bottom-right region. The old avg<100 rule failed on any photo
          // with a bright corner (sky/white hull/bulkhead/cabin headliner).
          // Must stay in sync with removeDateStampFromPhoto.
          const _stampPixels = ctx.getImageData(_sx, _sy, _rw, _rh);
          const _d = _stampPixels.data;
          const _pixelCount = _d.length / 4;
          let _darkCount = 0, _brightCount = 0;
          for (let _i = 0; _i < _d.length; _i += 4) {
            const _b = (_d[_i] + _d[_i+1] + _d[_i+2]) / 3;
            if (_b < 80) _darkCount++;
            else if (_b > 220) _brightCount++;
          }
          const _darkPct = (100 * _darkCount) / _pixelCount;
          const _brightPct = (100 * _brightCount) / _pixelCount;
          if (_darkPct > 30 && _brightPct > 1.5) {
            // Sample a thin strip just above the stamp
            const _sampleH = Math.min(2, _sy);
            if (_sampleH > 0) {
              const _strip = ctx.getImageData(_sx, _sy - _sampleH, _rw, 1);
              for (let _row = 0; _row < _rh; _row++) {
                ctx.putImageData(_strip, _sx, _sy + _row);
              }
            }
          }
        }
      } catch (_e) { console.warn('stamp removal skipped:', _e); }

      resolve(canvas.toDataURL('image/jpeg', quality));
    };
    img.onerror = () => resolve(dataUrl); // fallback to original on error
    img.src = dataUrl;
  });
}

// Camera active flag — persisted to sessionStorage so it survives
// iOS Chrome tab suspension when the camera app is open.
function setCameraActive(val) {
  window._cameraActive = val;
  _kkCameraActive = !!val;
  if (val) {
    try {
      sessionStorage.setItem('_cameraActive', '1');
      if (currentSurveyId) {
        sessionStorage.setItem('_cameraSurveyId', currentSurveyId);
      }
    } catch (e) { /* sessionStorage may not be available in some contexts */ }
  } else {
    try {
      sessionStorage.removeItem('_cameraActive');
    } catch (e) {}
    _checkDeferredUpdate();
  }
}

// Capitalize each word in a string (for name fields)
function capitalizeWords(str) {
  if (!str) return str;
  return str.replace(/\b\w/g, c => c.toUpperCase());
}

// Extract short location name (marina/yard + city) from full address
function shortLocation(fullLocation) {
  if (!fullLocation) return '';
  // Split by commas
  const parts = fullLocation.split(',').map(p => p.trim());
  if (parts.length <= 2) return fullLocation;

  // Look for marina/yacht club/yard/harbour keywords in first parts
  const venueKeywords = /marina|yacht|club|harbour|harbor|boat|yard|wharf|dock|pier|bay|port|landing|shipyard/i;
  let venue = '';
  let city = '';

  for (let i = 0; i < parts.length; i++) {
    if (!venue && venueKeywords.test(parts[i])) {
      venue = parts[i];
    }
    // City is typically the 2nd or 3rd part (after venue/street)
    if (!city && i > 0 && i < parts.length - 1 && !/^\d/.test(parts[i]) && !parts[i].match(/^[A-Z]\d[A-Z]\s?\d[A-Z]\d$/i) && parts[i].length > 2) {
      // Skip postal codes and province abbreviations
      if (!parts[i].match(/^(ON|BC|AB|SK|MB|QC|NB|NS|PE|NL|NT|NU|YT|Canada)$/i)) {
        city = parts[i];
      }
    }
  }

  if (venue && city && venue !== city) return `${venue}, ${city}`;
  if (venue) return venue;
  // No venue found — use street address + city
  if (parts.length >= 2) {
    const street = parts[0];
    // Find the city (skip postal codes, provinces, country)
    for (let i = 1; i < parts.length; i++) {
      if (!parts[i].match(/^[A-Z]\d[A-Z]\s?\d[A-Z]\d$/i) && !parts[i].match(/^(ON|BC|AB|SK|MB|QC|NB|NS|PE|NL|NT|NU|YT|Canada)$/i) && parts[i].length > 2) {
        return `${street}, ${parts[i]}`;
      }
    }
    return `${street}, ${parts[1]}`;
  }
  return fullLocation;
}

// v2463: Report-grade address formatter. shortLocation() above is for UI labels
// (tab title, survey card, etc) where we want "Venue, City" only. This one is
// for the formal "Location of Survey Inspection" line in the report body — we
// want the full mailing address, but stripped of Nominatim's geocoder artefacts
// (suburb, "Peel Region", "Golden Horseshoe", "Canada"), with the province
// abbreviated, and house number joined to the street name with a space instead
// of a comma.
//
// Target format: "Port Credit Yacht Club, 115 Lakefront Promenade, Mississauga, ON L5E 3G9"
//
// Rules applied to the Nominatim display_name:
//   - Drop parts matching /Region$| Horseshoe$|^Canada$/i (geocoder noise).
//   - Abbreviate Canadian province names to their two-letter codes.
//   - Join a pure-digit part (house number) with the next part using a space.
//   - Drop the "suburb" / neighbourhood part — heuristic: the sub-city part
//     immediately before the city, only when we can identify both. Conservative:
//     if we can't tell which one is the suburb, we leave both in and let the
//     surveyor tidy it up in Edit Vessel Info.
function formatReportLocation(fullLocation) {
  if (!fullLocation) return '';
  const rawParts = fullLocation.split(',').map(p => p.trim()).filter(Boolean);
  if (rawParts.length <= 2) return fullLocation;

  const provinceMap = {
    'ontario': 'ON', 'british columbia': 'BC', 'alberta': 'AB',
    'saskatchewan': 'SK', 'manitoba': 'MB', 'quebec': 'QC', 'québec': 'QC',
    'new brunswick': 'NB', 'nova scotia': 'NS', 'prince edward island': 'PE',
    'newfoundland and labrador': 'NL', 'northwest territories': 'NT',
    'nunavut': 'NU', 'yukon': 'YT',
  };
  const postalRE = /^[A-Z]\d[A-Z]\s?\d[A-Z]\d$/i;
  const noiseRE  = /(^|\s)Region$| Horseshoe$|^Regional Municipality\b|^County$|^Canada$/i;

  // Pass 1: drop noise, normalise province.
  let parts = [];
  for (const p of rawParts) {
    if (noiseRE.test(p)) continue;
    const key = p.toLowerCase();
    if (provinceMap[key]) parts.push(provinceMap[key]);
    else parts.push(p);
  }

  // Pass 2: join pure-digit part (house number) with the next part.
  const joined = [];
  for (let i = 0; i < parts.length; i++) {
    if (/^\d+[A-Z]?$/i.test(parts[i]) && i + 1 < parts.length) {
      joined.push(`${parts[i]} ${parts[i + 1]}`);
      i++;
    } else {
      joined.push(parts[i]);
    }
  }

  // Pass 3: merge the province + postal code into one comma-less segment
  // ("ON L5E 3G9" not "ON, L5E 3G9") per Canada Post guidelines.
  const result = [];
  for (let i = 0; i < joined.length; i++) {
    const cur = joined[i];
    const next = joined[i + 1];
    if (/^[A-Z]{2}$/.test(cur) && next && postalRE.test(next)) {
      result.push(`${cur} ${next}`);
      i++;
    } else {
      result.push(cur);
    }
  }

  return result.join(', ');
}

// Color mapping for ratings
const RATING_COLORS = {
  'A - Critical': '#dc2626',
  'B - Needs Attention': '#d97706',
  'C - Serviceable': '#16a34a',
  'Safety Equipment': '#2563eb',
  'Powered up only': '#6b7280',
  'Not applicable': '#6b7280',
  'Not tested/not verified': '#6b7280'
};

// Short display labels for rating buttons (keeps full internal key unchanged)
const RATING_SHORT_LABELS = {
  'A - Critical': 'A',
  'B - Needs Attention': 'B',
  'C - Serviceable': 'C',
  'Powered up only': 'PO',
  'Not tested/not verified': 'Not Tested',
  'Not applicable': 'NA'
};

function getRatingShortLabel(rating) {
  return RATING_SHORT_LABELS[rating] || rating;
}

// v2228: single source of truth for how the report labels, colours, and
// classes each rating. Previous code used `rating.startsWith('A') ? … :
// rating.startsWith('B') ? … : rating.startsWith('C') ? … : 'NT'`
// fallthrough patterns that silently grouped "Not applicable" and
// "Powered up only" into the 'NT' bucket — so NA items were rendered
// as "NT — Not Tested" in the checklist summary and tagged `rating-nt`
// in the body. Use this helper everywhere in the report-gen path
// instead of hand-rolled startsWith chains.
function classifyRatingForReport(rating) {
  const r = String(rating || '');
  if (r.startsWith('A')) return { code: 'A', label: 'Critical', color: '#dc2626', cssClass: 'rating-a' };
  if (r.startsWith('B')) return { code: 'B', label: 'Needs Attention', color: '#d97706', cssClass: 'rating-b' };
  if (r.startsWith('C')) return { code: 'C', label: 'Serviceable', color: '#16a34a', cssClass: 'rating-c' };
  if (r.startsWith('Powered')) return { code: 'PO', label: 'Powered Up Only', color: '#6b7280', cssClass: 'rating-po' };
  if (r.startsWith('Not applicable') || r.toLowerCase() === 'n/a' || r.toLowerCase() === 'na') {
    return { code: 'NA', label: 'Not Applicable', color: '#6b7280', cssClass: 'rating-na' };
  }
  if (r.startsWith('Not tested') || r.startsWith('Not verified') || r === 'NT') {
    return { code: 'NT', label: 'Not Tested', color: '#6b7280', cssClass: 'rating-nt' };
  }
  return { code: (r.charAt(0) || '?').toUpperCase(), label: r || '—', color: '#6b7280', cssClass: 'rating-nt' };
}

// v2386: On power boats, the rudder (if any) is typically bronze and is NOT
// subject to impact/percussion/resonance testing the way a fibreglass sail-boat
// rudder would be. For the hull-and-rudder resonance testing item specifically,
// treat the vessel as if it had no rudder so the label, snippet chips, and
// saved-text expansion all drop rudder verbiage.
//
// v2429: extended to cover conductivity testing too. A bronze rudder has no
// fibreglass laminate, so a moisture-meter reading on it is meaningless. We
// strip the rudder verbiage from the conductivity chip set on power boats
// the same way we do for resonance — same predicate, same scrubber path.
// Renamed isPowerBoatRudderResonanceItem → isPowerBoatHullRudderTest to
// reflect the broader scope. (Old name kept as window alias for safety.)
function isPowerBoatHullRudderTest(survey, label) {
  if (!survey || !label) return false;
  if (String(survey.vesselType || '').toLowerCase() !== 'power') return false;
  // Matches both the raw template form ("Hull and rudder(s) (if applicable)
  // X testing") and the library section form ("Hull and rudder(s) X testing"),
  // plus any legacy "percussion testing" phrasing from earlier template renames.
  return /^hull\s+and\s+rudder/i.test(label) &&
         /(impact\s+and\s+resonance|percussion|conductivity)\s+testing/i.test(label);
}
// v2386 alias — keep the old name resolvable in case any external/future code
// references it. Internal call sites use the new name directly.
const isPowerBoatRudderResonanceItem = isPowerBoatHullRudderTest;

// v2386: Return the snippet-expansion context for a specific item, applying
// the power-boat hull-resonance override. Drop-in replacement for the inline
// `contextFromSurvey(survey)` calls at snippet-expansion sites — just pass
// the item label so the override can fire when appropriate. When itemLabel
// is omitted or the override doesn't apply, behaviour matches the original
// inline pattern exactly.
function _itemSnippetCtx(survey, itemLabel) {
  let ctx = (window.KikiSnippetTokens && window.KikiSnippetTokens.contextFromSurvey)
    ? window.KikiSnippetTokens.contextFromSurvey(survey)
    : { hasRudder: survey && survey.hasRudder !== false,
        rudderCount: (survey && parseInt(survey.rudderCount, 10)) || 1 };
  if (survey && itemLabel && isPowerBoatRudderResonanceItem(survey, itemLabel)) {
    ctx = Object.assign({}, ctx, { hasRudder: false, rudderCount: 0 });
  }
  return ctx;
}

// v2387: Light grammatical polish of snippet prose after a chip tap.
// Only runs on chip-tap / sentence-picker insertion paths — hand-typed text
// is never reformatted. Scope (per Dave):
//   • Trigger: live, on every tap.
//   • Aggressiveness: light — dedupe only. No sentence rewriting.
//   • Order: preserve tap order; never shuffle sentences.
//
// Concretely the polish does three things:
//   1. Drop any sentence that is a strict prefix of another sentence already in
//      the text (keep the longer, more-specific sentence at its original spot).
//      Example: tapping "Impact and resonance testing was carried out across
//      the hull." followed by "Impact and resonance testing was carried out
//      across the hull and rudder(s)." → keep only the second.
//   2. Drop exact duplicates (case-insensitive, terminator-insensitive), keeping
//      the FIRST occurrence so the original tap order is preserved.
//   3. Tidy whitespace — collapse double spaces and remove spaces before
//      punctuation. No capitalization, no rewriting.
//
// Non-goals for v2387: verb-agreement fixes, re-ordering, article cleanup,
// paraphrasing, capitalization. Those are structural rewrites and out of
// scope for "light / dedupe only" polish.
function polishSnippetProse(text) {
  if (!text || typeof text !== 'string') return text || '';
  // Split the input into sentence units while preserving trailing punctuation.
  // Anything that follows the final terminator is captured as a trailing
  // fragment (e.g. a half-typed sentence the surveyor hasn't punctuated yet)
  // and appended at the end so we never truncate in-progress input.
  const sentences = [];
  const re = /([^.!?]+[.!?]+)(\s*)/g;
  let m;
  let lastIdx = 0;
  while ((m = re.exec(text)) !== null) {
    sentences.push(m[1].trim());
    lastIdx = m.index + m[0].length;
  }
  const trailing = text.slice(lastIdx).trim();
  if (trailing) sentences.push(trailing);
  if (sentences.length < 2) {
    // Nothing to compare against — just normalize whitespace and return.
    return text.replace(/\s+([,.;:!?])/g, '$1').replace(/\s{2,}/g, ' ').trim();
  }

  // Normalized form used for comparison. Strip trailing terminators so
  // "The hull was tested" matches "The hull was tested." and tolerate
  // case differences.
  const norm = s => s.toLowerCase()
                     .replace(/[.!?]+$/, '')
                     .replace(/\s+/g, ' ')
                     .trim();
  const normalized = sentences.map(norm);
  const keep = new Array(sentences.length).fill(true);

  for (let i = 0; i < sentences.length; i++) {
    if (!keep[i]) continue;
    const ni = normalized[i];
    if (!ni) { keep[i] = false; continue; }
    for (let j = 0; j < sentences.length; j++) {
      if (i === j || !keep[j]) continue;
      const nj = normalized[j];
      // (1) Strict prefix — drop the shorter sentence, regardless of position.
      if (nj.length > ni.length && nj.startsWith(ni + ' ')) {
        keep[i] = false;
        break;
      }
      // (2) Exact duplicate — keep the FIRST occurrence, drop later copies.
      if (ni === nj && j < i) {
        keep[i] = false;
        break;
      }
    }
  }

  const out = [];
  for (let i = 0; i < sentences.length; i++) {
    if (keep[i]) out.push(sentences[i]);
  }
  // Rejoin with single spaces and run the same whitespace cleanup the token
  // expander uses so the final output doesn't show double-spaces or space
  // before punctuation.
  return out.join(' ')
            .replace(/\s+([,.;:!?])/g, '$1')
            .replace(/\s{2,}/g, ' ')
            .trim();
}

// Transform a raw checklist-item label into its display form for the current
// survey — applies rudder-gating so "Hull and rudder(s) (if applicable) X"
// becomes "Hull X" on no-rudder vessels, "Hull and rudder X" on single-rudder,
// and "Hull and rudders X" on twin-rudder. Internal keys (survey.items map)
// continue to use the raw label — this is for DISPLAY only.
// The survey arg is optional; defaults to the window-cached current survey.
function displayItemLabel(rawLabel, survey) {
  if (!rawLabel) return '';
  const s = survey || window._currentSurveyCache || null;
  if (!s) return rawLabel;
  // v2275: apply rudder pluralization to labels even without transformLabelForDisplay
  let label = rawLabel;
  if (typeof window.transformLabelForDisplay === 'function') {
    let ctx = (window.KikiSnippetTokens && window.KikiSnippetTokens.contextFromSurvey)
      ? window.KikiSnippetTokens.contextFromSurvey(s)
      : { hasRudder: s.hasRudder !== false, rudderCount: parseInt(s.rudderCount, 10) || 1 };
    // v2386: force no-rudder for the power-boat hull resonance testing item
    if (isPowerBoatRudderResonanceItem(s, rawLabel)) {
      ctx = Object.assign({}, ctx, { hasRudder: false, rudderCount: 0 });
    }
    label = window.transformLabelForDisplay(rawLabel, ctx);
  }
  // v2386: if we just forced no-rudder, skip rudder pluralization so we don't
  // re-insert rudders into a label we deliberately stripped.
  if (isPowerBoatRudderResonanceItem(s, rawLabel)) return label;
  return pluralizeRudder(label, s.rudderCount);
}

