// Delete a single safety equipment photo
async function deleteSafetyPhoto(idx, photoId) {
  const survey = await getSurvey(currentSurveyId);
  if (!survey || !survey.safetyEquipment[idx]) return;
  // Remove from photos array
  survey.safetyEquipment[idx].photos = (survey.safetyEquipment[idx].photos || []).filter(p => p !== photoId);
  await saveSurvey(survey);
  // Delete photo from IndexedDB
  try { await deletePhoto(photoId); } catch(e) { /* ignore */ }
  // Refresh thumbnails
  loadSafetyThumbnails(idx, survey.safetyEquipment[idx].photos);
  showToast('Photo deleted');
}

// Load all safety thumbnails after rendering
async function loadAllSafetyThumbnails() {
  const survey = await getSurvey(currentSurveyId);
  if (!survey || !survey.safetyEquipment) return;
  survey.safetyEquipment.forEach((eq, idx) => {
    if (eq.photos && eq.photos.length > 0) {
      loadSafetyThumbnails(idx, eq.photos);
    }
  });
}

// v2366: Attach dragged/imported photos to a safety equipment item.
// Mirrors attachPhotosToItem but stores photo IDs under
// survey.safetyEquipment[idx].photos rather than survey.items[label].photos.
async function attachPhotosToSafetyItem(idx, fileList) {
  const files = Array.from(fileList || []).filter(f => {
    if (!f) return false;
    if (f.type && f.type.startsWith('image/')) return true;
    return /\.(heic|heif)$/i.test(f.name || '');
  });
  if (files.length === 0) {
    showToast('No image files selected');
    return 0;
  }

  const heicCount = files.filter(isHeicFile).length;
  if (heicCount > 0) {
    showToast(`Converting ${heicCount} HEIC photo${heicCount === 1 ? '' : 's'}…`);
  } else if (files.length > 1) {
    showToast(`Saving ${files.length} photos…`);
  }

  // Resolve the safety item name up front for labeling photo records.
  const preSurvey = await getSurvey(currentSurveyId);
  if (!preSurvey || !preSurvey.safetyEquipment || !preSurvey.safetyEquipment[idx]) {
    showToast('Safety item not found');
    return 0;
  }
  const eqName = preSurvey.safetyEquipment[idx].name || `Safety item ${idx}`;

  let saved = 0;
  let heicFailed = 0;
  for (const file of files) {
    await new Promise(async (resolve) => {
      try {
        let dataUrl = null;
        if (isHeicFile(file)) {
          dataUrl = await heicToJpegDataUrl(file);
          if (!dataUrl) { heicFailed++; resolve(); return; }
        } else {
          dataUrl = await new Promise((res) => {
            const reader = new FileReader();
            reader.onload = (ev) => res(ev.target.result);
            reader.onerror = () => res(null);
            reader.readAsDataURL(file);
          });
          if (!dataUrl) { resolve(); return; }
        }

        const stamped = (typeof addDateStampToPhoto === 'function')
          ? await addDateStampToPhoto(dataUrl)
          : dataUrl;

        if (!/^data:image\/(jpeg|jpg|png|webp|gif)[;,]/i.test(stamped)) {
          console.error('attachPhotosToSafetyItem: refusing to save non-renderable format', stamped.substring(0, 40));
          heicFailed++;
          resolve();
          return;
        }

        const photoId = `safety_${currentSurveyId}_${idx}_${Date.now()}_${Math.random().toString(36).substr(2, 4)}`;
        const photo = {
          id: photoId,
          surveyId: currentSurveyId,
          itemLabel: eqName,
          dataUrl: stamped,
          annotated: false,
          createdAt: new Date().toISOString()
        };
        await savePhoto(photo);
        // Re-fetch inside the loop so concurrent saves don't clobber each
        // other's photo-array updates.
        const survey = await getSurvey(currentSurveyId);
        if (!survey.safetyEquipment || !survey.safetyEquipment[idx]) { resolve(); return; }
        if (!Array.isArray(survey.safetyEquipment[idx].photos)) {
          survey.safetyEquipment[idx].photos = [];
        }
        survey.safetyEquipment[idx].photos.push(photoId);
        // v2378: drop pixel-identical duplicates within this safety item's photos
        try {
          const _dd = await dedupePhotosWithinArray(survey.safetyEquipment[idx].photos);
          survey.safetyEquipment[idx].photos = _dd.kept;
        } catch (_) {}
        await saveSurvey(survey);
        saved++;
      } catch (err) {
        console.error('attachPhotosToSafetyItem error:', err);
      }
      resolve();
    });
  }

  // Refresh thumbnails and the 📷 count badge without a full re-render.
  try {
    const survey = await getSurvey(currentSurveyId);
    const photos = (survey.safetyEquipment[idx] && survey.safetyEquipment[idx].photos) || [];
    loadSafetyThumbnails(idx, photos);
    // Update the camera button count — it's the button inside the wrapper
    // that calls captureSafetyPhoto(idx). Match by onclick attribute.
    const wrapper = document.querySelector(`.safety-item-wrapper[data-safety-idx="${idx}"]`);
    if (wrapper) {
      const camBtn = wrapper.querySelector(`button[onclick="captureSafetyPhoto(${idx})"]`);
      if (camBtn) camBtn.innerHTML = `📷${photos.length > 0 ? ` ${photos.length}` : ''}`;
    }
  } catch (_) {}

  if (heicFailed > 0 && saved === 0) {
    showToast(`Could not convert ${heicFailed} HEIC photo${heicFailed === 1 ? '' : 's'} — try converting to JPG in Preview first`);
  } else if (heicFailed > 0) {
    showToast(`Attached ${saved} photo${saved === 1 ? '' : 's'} • ${heicFailed} HEIC failed`);
  } else {
    showToast(`Attached ${saved} photo${saved === 1 ? '' : 's'}`);
  }
  return saved;
}

// v2366: File picker for safety-equipment items (Photo Library + Files app).
function importPhotosForSafetyItem(idx) {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  input.multiple = true;
  input.onchange = () => attachPhotosToSafetyItem(idx, input.files);
  if (typeof setCameraActive === 'function') setCameraActive(true);
  input.click();
}

// ── Instruments & Electronics Functions ─────────────────────────────────

// Rapid capture — camera keeps reopening until user cancels
function rapidCaptureInstruments() {
  let count = 0;

  function takeNext() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.capture = 'environment';
    input.onchange = async (e) => {
      const files = Array.from(e.target.files);
      if (files.length === 0) {
        // User cancelled — done
        if (count > 0) {
          showToast(`${count} instrument${count > 1 ? 's' : ''} captured — review below`);
          const survey = await getSurvey(currentSurveyId);
          if (survey) renderInspection(survey);
        }
        return;
      }

      const file = files[0];
      // v2403: FileReader hang hardening — failure here must still continue
      // the rapid-capture flow (reopen camera) so the surveyor isn't stranded.
      const reader = new FileReader();
      reader.onload = async (re) => {
        try {
          const stampedDataUrl = await addDateStampToPhoto(re.target.result, 2048);
          const survey = await getSurvey(currentSurveyId);
          if (!survey) return;
          if (!survey.instrumentsElectronics) survey.instrumentsElectronics = [];

          const idx = survey.instrumentsElectronics.length;
          const photoId = `instrument_${currentSurveyId}_${idx}_${Date.now()}_${Math.random().toString(36).substr(2, 4)}`;
          const photo = {
            id: photoId,
            surveyId: currentSurveyId,
            itemLabel: `instrument_${idx}`,
            dataUrl: stampedDataUrl,
            annotated: false,
            createdAt: new Date().toISOString()
          };
          await savePhoto(photo);

          survey.instrumentsElectronics.push({
            name: '',
            make: '',
            model: '',
            year: '',
            working: null,
            notes: '',
            photos: [photoId],
            aiIdentified: false,
            aiDetails: ''
          });
          await saveSurvey(survey);
          count++;
          showToast(`Photo ${count} saved — take next or cancel to finish`);
        } catch (err) {
          console.error('rapidCaptureInstruments: failed to process photo', err);
          showToast('⚠️ One instrument photo failed — continuing');
        } finally {
          // Always reopen camera for next shot, even on failure
          setTimeout(() => takeNext(), 300);
        }
      };
      reader.onerror = () => {
        console.error('rapidCaptureInstruments: FileReader error', reader.error);
        showToast('⚠️ Could not read photo — continuing');
        setTimeout(() => takeNext(), 300);
      };
      reader.readAsDataURL(file);
    };
    setCameraActive(true);
    input.click();
  }

  showToast('Rapid capture: take photos, cancel when done');
  takeNext();
}

// Add instrument by taking a photo first
async function addInstrumentByPhoto() {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  input.multiple = true;  // allow multiple selection from camera roll — creates one instrument per photo
  // No capture attribute — allows camera roll, files, or camera
  input.onchange = async (e) => {
    const files = Array.from(e.target.files);
    if (files.length === 0) return;

    showToast('Saving photo...');

    const survey = await getSurvey(currentSurveyId);
    if (!survey) return;
    if (!survey.instrumentsElectronics) survey.instrumentsElectronics = [];

    // v2403: FileReader hang hardening — see capturePhoto for rationale.
    for (const file of files) {
      await new Promise((resolve) => {
        const reader = new FileReader();
        reader.onload = async (re) => {
          try {
            const stampedDataUrl = await addDateStampToPhoto(re.target.result, 2048);
            const idx = survey.instrumentsElectronics.length;
            const photoId = `instrument_${currentSurveyId}_${idx}_${Date.now()}_${Math.random().toString(36).substr(2, 4)}`;
            const photo = {
              id: photoId,
              surveyId: currentSurveyId,
              itemLabel: `instrument_${idx}`,
              dataUrl: stampedDataUrl,
              annotated: false,
              createdAt: new Date().toISOString()
            };
            await savePhoto(photo);

            survey.instrumentsElectronics.push({
              name: '',
              make: '',
              model: '',
              year: '',
              working: null,
              notes: '',
              photos: [photoId],
              aiIdentified: false,
              aiDetails: ''
            });
          } catch (err) {
            console.error('addInstrumentByPhoto: failed to process photo', err);
            showToast('⚠️ One instrument photo failed — continuing');
          } finally {
            resolve();
          }
        };
        reader.onerror = () => {
          console.error('addInstrumentByPhoto: FileReader error', reader.error);
          showToast('⚠️ Could not read photo — continuing');
          resolve();
        };
        reader.readAsDataURL(file);
      });
    }

    await saveSurvey(survey);
    showToast('Instrument added — tap Identify to auto-fill details');
    renderInspection(survey);
  };
  setCameraActive(true);
  input.click();
}

